class Account:
    """A shopper's account.

    ``purchases`` may be any iterable, including a lazily loaded one that
    performs I/O as it is walked, so it is consumed exactly once here and the
    result kept as a tuple.  Nothing downstream may re-walk the caller's
    iterable: doing so per request is what turns a cheap summary into a
    multi-second one, and a one-shot iterable would come back empty the second
    time round.
    """

    def __init__(self, purchases, total_cents, total_this_month_cents):
        self.purchases = tuple(purchases)
        self.total_cents = total_cents
        self.total_this_month_cents = total_this_month_cents
        self._current_month_purchase_count = None

    @property
    def current_month_purchase_count(self):
        """How many purchases fall in the current month.

        Computed on first use and cached, so asking repeatedly costs nothing.
        """
        if self._current_month_purchase_count is None:
            self._current_month_purchase_count = sum(
                1 for purchase in self.purchases if purchase.in_current_month
            )
        return self._current_month_purchase_count

    def current_month_purchases(self):
        return tuple(p for p in self.purchases if p.in_current_month)

from io_shop.accounts import Account
from io_shop.spend_summary import average_spend_per_item_this_month


class Purchase:
    def __init__(self, in_current_month=True):
        self.in_current_month = in_current_month


class CountingHistory:
    """A purchase history that records how often it is walked.

    Stands in for a lazily loaded history where each walk costs I/O.
    """

    def __init__(self, purchases):
        self._purchases = list(purchases)
        self.walks = 0

    def __iter__(self):
        self.walks += 1
        return iter(self._purchases)


def test_the_monthly_average_is_correct_for_a_shopper_who_did_buy():
    account = Account(
        purchases=[Purchase(), Purchase(), Purchase(), Purchase()],
        total_cents=10_000,
        total_this_month_cents=1_000,
    )

    assert average_spend_per_item_this_month(account) == 250


def test_purchases_outside_the_current_month_are_not_counted():
    account = Account(
        purchases=[
            Purchase(in_current_month=True),
            Purchase(in_current_month=True),
            Purchase(in_current_month=False),
            Purchase(in_current_month=False),
        ],
        total_cents=10_000,
        total_this_month_cents=900,
    )

    assert average_spend_per_item_this_month(account) == 450


def test_a_shopper_with_no_purchases_this_month_averages_zero():
    account = Account(
        purchases=[Purchase(in_current_month=False)],
        total_cents=10_000,
        total_this_month_cents=0,
    )

    assert average_spend_per_item_this_month(account) == 0


def test_a_shopper_with_no_purchases_at_all_averages_zero():
    account = Account(purchases=[], total_cents=0, total_this_month_cents=0)

    assert average_spend_per_item_this_month(account) == 0


def test_the_totals_the_summary_reads_are_kept_on_the_account():
    account = Account(
        purchases=[Purchase()], total_cents=10_000, total_this_month_cents=1_500
    )

    assert account.total_cents == 10_000
    assert account.total_this_month_cents == 1_500


def test_the_purchase_history_is_walked_once_however_often_we_summarise():
    history = CountingHistory([Purchase() for _ in range(3)])
    account = Account(
        purchases=history, total_cents=10_000, total_this_month_cents=300
    )

    for _ in range(50):
        assert average_spend_per_item_this_month(account) == 100

    assert history.walks == 1


def test_a_one_shot_purchase_history_still_summarises_correctly():
    purchases = (Purchase() for _ in range(2))
    account = Account(
        purchases=purchases, total_cents=10_000, total_this_month_cents=500
    )

    assert average_spend_per_item_this_month(account) == 250
    assert average_spend_per_item_this_month(account) == 250
